package org.millenaire.common.entity;import net.minecraft.world.entity.*;import org.millenaire.common.utilities.*;import org.millenaire.common.village.*;import org.millenaire.common.item.*;import net.minecraft.world.level.block.state.BlockState;public class MillVillager extends Entity{public Point destination;public Building house;public int seeds,swings;public MillVillager(){super(EntityType.PIG,null);}protected void defineSynchedData(){}protected void readAdditionalSaveData(net.minecraft.nbt.CompoundTag t){}protected void addAdditionalSaveData(net.minecraft.nbt.CompoundTag t){}public net.minecraft.network.protocol.Packet<?> getAddEntityPacket(){return null;}public Building getGoalBuildingDest(){return house;}public Point getGoalDestPoint(){return destination;}public Point getPos(){return new Point(0,0,0);}public int countInv(InvItem i){return seeds;}public int takeFromInv(InvItem i,int n){int taken=Math.min(seeds,n);seeds-=taken;return taken;}public boolean setBlockstate(Point p,BlockState s){Point.cells.put(p.pos,s);return true;}public void swing(net.minecraft.world.InteractionHand h){swings++;}public void setGoalInformation(org.millenaire.common.goal.Goal.GoalInformation info){}}